"use client";

import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import * as TogglePrimitive from "@radix-ui/react-toggle";
import * as React from "react";

import { cn } from "@/lib/utils";

const toggleVariants = cva(
  "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-[color,box-shadow] outline-none hover:bg-muted hover:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    defaultVariants: {
      size: "default",
      variant: "default",
    },
    variants: {
      size: {
        default: "h-9 min-w-9 px-2",
        icon: "size-9",
        "icon-sm": "size-8",
        lg: "h-10 min-w-10 px-2.5",
        sm: "h-8 min-w-8 px-1.5",
      },
      variant: {
        default: "bg-transparent",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50 data-[state=on]:bg-accent/80 data-[state=on]:text-accent-foreground",
        outline:
          "border border-input bg-transparent shadow-xs hover:bg-accent hover:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 data-[state=on]:bg-secondary/60",
      },
    },
  },
);

const Toggle = ({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> & VariantProps<typeof toggleVariants>) => (
  <TogglePrimitive.Root
    data-slot="toggle"
    className={cn(toggleVariants({ className, size, variant }))}
    {...props}
  />
);

export { Toggle, toggleVariants };
export default Toggle;

"use client";

import { BoldIcon, ItalicIcon, MicIcon, MicOffIcon, StarIcon, UnderlineIcon } from "lucide-react";
import { useState } from "react";

import { Toggle } from "@/components/ui/toggle";

export function ToggleDemo() {
  const [muted, setMuted] = useState(false);

  return (
    <div className="flex flex-col gap-6">
      {/* Default — text */}
      <div className="flex flex-wrap gap-2">
        <Toggle>Bold</Toggle>
        <Toggle defaultPressed>Pressed</Toggle>
        <Toggle disabled>Disabled</Toggle>
      </div>

      {/* With icon */}
      <div className="flex flex-wrap gap-2">
        <Toggle aria-label="Bold">
          <BoldIcon />
        </Toggle>
        <Toggle aria-label="Italic" defaultPressed>
          <ItalicIcon />
        </Toggle>
        <Toggle aria-label="Underline">
          <UnderlineIcon />
        </Toggle>
      </div>

      {/* Outline variant */}
      <div className="flex flex-wrap gap-2">
        <Toggle variant="outline" aria-label="Bold">
          <BoldIcon />
          Bold
        </Toggle>
        <Toggle variant="outline" aria-label="Italic" defaultPressed>
          <ItalicIcon />
          Italic
        </Toggle>
        <Toggle variant="outline" aria-label="Underline">
          <UnderlineIcon />
          Underline
        </Toggle>
      </div>

      {/* Sizes */}
      <div className="flex flex-wrap items-center gap-2">
        <Toggle size="sm" aria-label="Favourite">
          <StarIcon />
        </Toggle>
        <Toggle size="default" aria-label="Favourite">
          <StarIcon />
        </Toggle>
        <Toggle size="lg" aria-label="Favourite">
          <StarIcon />
        </Toggle>
      </div>

      {/* Controlled — mute toggle */}
      <div className="flex items-center gap-3">
        <Toggle
          pressed={muted}
          onPressedChange={setMuted}
          variant="outline"
          aria-label={muted ? "Unmute" : "Mute"}
        >
          {muted ? <MicOffIcon /> : <MicIcon />}
          {muted ? "Unmuted" : "Mute"}
        </Toggle>
        <span className="text-muted-foreground text-sm">
          Microphone is {muted ? "muted" : "active"}
        </span>
      </div>
    </div>
  );
}


export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-8 bg-background">
      <ToggleDemo />
    </div>
  );
}
